package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.*;
import com.lianxibu.site.service.articles.*;
import com.lianxibu.site.service.content.FrozenPublicMetadata;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** Pure profile over actual native day/allocation captures. Request construction remains local and unpaid. */
class CatalogAnalysisInputProfileTest {
    final FrozenGenerationSettings settings=new FrozenGenerationSettings(3,List.of("fictional-interest"),List.of("fictional-block"));boolean mysql(){return false;}
    CatalogDayAnalysisInputPermitTest helper(){return new CatalogDayAnalysisInputPermitTest(){@Override boolean mysql(){return CatalogAnalysisInputProfileTest.this.mysql();}};}
    record Built(CatalogDayAnalysisInputPermitTest helper,CatalogDayAnalysisInputPermitTest.Built data,CatalogDayAnalysisInputPermitService provider,CatalogDayAnalysisInputPermitService.Captured captured){ }
    Built fixture(String category,boolean alias){var helper=helper();var data=helper.fresh(category,alias);var provider=helper.provider(data);return new Built(helper,data,provider,provider.capture(data.outer().day,data.receipt().entityId()));}
    JsonNode enrich(Built built,CatalogAnalysisInputProfile.Base base){var f=built.data().f();return f.write(()->{built.provider().verify(built.captured());var source=new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.f.source));var actual=new AnalysisPublicMetadataEnricher(new EntityInputEvidenceService(new JdbcEntityDedup(f.f.source),source),new ArticlePublicEvidenceService(new JdbcArticlePublicEvidence(f.f.source),source));var snapshot=(ObjectNode)CanonicalJson.parse(base.snapshotJson());var fields=actual.fields("fictional-next-analysis-root",base.command(),built.captured().dayEvidence().original().cutoff(),snapshot);snapshot.set(FrozenPublicMetadata.FIELD,fields.get(FrozenPublicMetadata.FIELD));return snapshot;});}
    @Test void FourCategoriesFullOriginalBodiesClosedContextSettingsAndNativeRootDependencies(){for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category,false);int jobs=built.data().f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var base=CatalogAnalysisInputProfile.create(built.captured(),settings);var snapshot=CanonicalJson.parse(base.snapshotJson());assertEquals(category+"_analysis",snapshot.get("stage").asText());assertEquals(built.data().receipt().entityId(),base.command().applicationContext().input("fictional-root","fictional-attempt",CanonicalJson.hash(CanonicalJson.Domain.INPUT,snapshot),0).targetEntityId());assertEquals(settings.semanticHash(),base.command().settingsHash());assertNull(base.command().sourceId());assertEquals(1,base.command().evidence().size());assertEquals(built.captured().entity().members().getFirst().bodyJson(),base.command().evidence().getFirst().bodyJson());assertEquals(built.captured().dayEvidence().original().cutoff(),WireValues.utcMicroseconds(snapshot.get("cutoff")));assertEquals(1,base.command().dependencies().size());assertEquals(built.captured().entity().members().getFirst().member().rootId(),base.command().dependencies().getFirst().id());assertEquals(2,snapshot.get(CatalogAnalysisInputProfile.FIELD).get("cohort").get("members").size());assertEquals("complete",snapshot.get("coverage_state").asText());assertTrue(snapshot.get("missing").isEmpty());assertEquals(base.command().applicationContext().json(),CatalogAnalysisInputProfile.readBase(snapshot).command().applicationContext().json());assertThrows(UnsupportedOperationException.class,()->base.command().evidence().clear());assertEquals(jobs,built.data().f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,built.data().f().f.sends);}}
    @Test void AliasBodiesAreAllPreservedAndActualPublicMetadataBuildsTheFullFormalRequest(){var built=fixture("agent",true);var base=CatalogAnalysisInputProfile.create(built.captured(),settings);assertEquals(2,base.command().evidence().size());assertEquals(2,base.command().evidence().stream().map(e->CanonicalJson.parse(e.bodyJson()).get("identity").get("key").asText()).distinct().count());assertEquals("fictional-analysis",base.command().applicationContext().contentId());assertEquals(1L,base.command().applicationContext().baseContentRevision());assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.complete(CanonicalJson.parse(base.snapshotJson())));var full=enrich(built,base);var complete=CatalogAnalysisInputProfile.complete(full);assertEquals(2,full.get(FrozenPublicMetadata.FIELD).get("citations").size());String hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,full);var request=CanonicalJson.parse(new GenerationRequestBuilder().build(complete.command().stage(),complete.snapshotJson(),hash));assertEquals(hash,request.get("input_hash").asText());assertEquals(2,built.data().f().f.sends);assertFalse(base.toString().contains("fictional"));}
    @Test void OriginalDeadlineMissingSourceRemainsPartialWithRealKnownDependenciesOnly(){var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.secondEnabled=true;f.terminal("workflow");f.completeSource();assertNotNull(f.barrier(Clock.fixed(SourceDedupBarrier.deadline(outer.day),ZoneOffset.UTC)).close(outer.day));var selection=outer.eligibility(f).capture(outer.day).selected().getFirst();var reserve=new CatalogDayAnalysisGenerationTest().service(outer,f,Clock.fixed(SourceDedupBarrier.deadline(outer.day).plusSeconds(60),ZoneOffset.UTC)).reserve(outer.day,selection.entity().entityId());var data=new CatalogDayAnalysisInputPermitTest.Built(outer,f,reserve);var provider=helper.provider(data);var captured=provider.capture(outer.day,reserve.entityId());var base=CatalogAnalysisInputProfile.create(captured,settings);var snapshot=CanonicalJson.parse(base.snapshotJson());assertEquals("partial",snapshot.get("coverage_state").asText());assertEquals(List.of("source:fictional-second"),snapshot.get("missing").valueStream().map(JsonNode::asText).toList());assertEquals(1,base.command().dependencies().size());assertEquals(base.command().dependencies().getFirst().id(),base.command().expectedDependencies().getFirst());assertEquals(2,snapshot.get(CatalogAnalysisInputProfile.FIELD).get("closure").get("sources").size());assertEquals(SourceDedupBarrier.deadline(outer.day),WireValues.utcMicroseconds(snapshot.get("cutoff")));assertEquals(2,f.f.sends);}
    @Test void OriginalBodyAnchorsSourceProofsClosureTargetAndSettingsCannotBeChanged(){var built=fixture("skill",false);var base=CatalogAnalysisInputProfile.create(built.captured(),settings);for(String field:List.of("logical_key","settings_hash","cutoff","coverage_state","business_date","stage")){var value=(ObjectNode)CanonicalJson.parse(base.snapshotJson());value.put(field,"fictional-invalid");assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(value));}var body=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)body.get("members").get(0)).put("body_hash","0".repeat(64));assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(body));var source=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)source.get(CatalogAnalysisInputProfile.FIELD).get("source_proofs").get(0)).put("final_result_hash","0".repeat(64));assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(source));var root=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)root.get(CatalogAnalysisInputProfile.FIELD).get("source_proofs").get(0).get("fragments").get(0)).put("input_hash","0".repeat(64));assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(root));var target=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)target.get(FrozenApplicationContext.FIELD).get("target_content")).put("id","fictional-wrong-target");assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(target));}
    @Test void MissingDuplicateReorderedMembersAndUnknownProfileFieldsReject(){var built=fixture("model",true);var base=CatalogAnalysisInputProfile.create(built.captured(),settings);var missing=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((tools.jackson.databind.node.ArrayNode)missing.get("members")).remove(1);assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(missing));var duplicate=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)duplicate.get("members").get(1)).put("id",duplicate.get("members").get(0).get("id").asText());assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(duplicate));var unknown=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)unknown.get(CatalogAnalysisInputProfile.FIELD)).put("unknown",true);assertThrows(RuntimeException.class,()->CatalogAnalysisInputProfile.readBase(unknown));}
    @Test void CompleteMaterialCapacityRejectsWithoutTruncatingOrChangingNativeState(){var built=fixture("agent",false);var base=CatalogAnalysisInputProfile.create(built.captured(),settings);int jobs=built.data().f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var huge=(ObjectNode)CanonicalJson.parse(base.snapshotJson());((ObjectNode)huge.get("members").get(0).get("body")).put("summary","x".repeat(CatalogAnalysisInputProfile.MAX_BYTES));assertThrows(GenerationFlowService.CapacityGuarded.class,()->CatalogAnalysisInputProfile.readBase(huge));assertEquals(jobs,built.data().f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(1,built.data().f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,built.data().f().f.sends);}
}
